CREATE TABLE tipo_documento (id BIGINT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(120) NOT NULL,descricao VARCHAR(500) NOT NULL,obrigatorio BOOLEAN NOT NULL,ativo BOOLEAN NOT NULL,versao_registro BIGINT NOT NULL,UNIQUE KEY uk_tipo_documento_nome(nome));
CREATE TABLE documento_academico (id BIGINT AUTO_INCREMENT PRIMARY KEY,aluno_id INT NOT NULL,tipo_documento_id BIGINT NOT NULL,nome_original VARCHAR(255) NOT NULL,tipo_mime VARCHAR(100) NOT NULL,tamanho_bytes BIGINT NOT NULL,chave_armazenamento CHAR(36) NOT NULL,situacao VARCHAR(20) NOT NULL,justificativa TEXT NULL,enviado_em DATETIME(6) NOT NULL,decidido_em DATETIME(6) NULL,versao_registro BIGINT NOT NULL,operacao_criacao CHAR(36) NOT NULL,UNIQUE KEY uk_documento_chave(chave_armazenamento),UNIQUE KEY uk_documento_operacao(operacao_criacao),INDEX ix_documento_aluno(aluno_id,situacao),INDEX ix_documento_tipo(tipo_documento_id,situacao),FOREIGN KEY(aluno_id) REFERENCES aluno(id),FOREIGN KEY(tipo_documento_id) REFERENCES tipo_documento(id),CHECK(situacao IN ('PENDENTE','APROVADO','RECUSADO')));
CREATE TABLE documento_academico_auditoria (id BIGINT AUTO_INCREMENT PRIMARY KEY,documento_id BIGINT NOT NULL,event VARCHAR(20) NOT NULL,autor_id BIGINT NOT NULL,instante DATETIME(6) NOT NULL,operacao_id CHAR(36) NOT NULL UNIQUE,origem VARCHAR(30) NOT NULL,FOREIGN KEY(documento_id) REFERENCES documento_academico(id));
